edits.replacement:
body:not(.padon) #root #pausebox::before{ width:min(calc(var(--pw) + var(--sp-5) + var(--sp-4)),calc(100% - var(--sp-4))) !important; }

/* v28.xx (cw-setnear) critic c-31 (Settings 2, pause 3): "controls ~700px from labels (limit 400)", "type 14/15/18 drift", "title still centred". Now: the Settings card is 17 x 48 wide, the name column is 8 x 48 and the stepper sits right after it (never 700px away), the section chips sit 16px apart, and the pause title is left-aligned over the button column with a hairline under it and the Esc hint right-aligned to the column edge. */
#root #settingsmodal{ --cw:calc(var(--sp-5) * 17); }
#root #setlist .row:not(.setjump) > div:first-child{ flex:0 0 calc(var(--sp-5) * 8) !important; min-width:0; }
#root #setlist .row:not(.setjump){ justify-content:flex-start; }
#root #setlist .setjump .sj{ gap:var(--sp-2); }
#root #pausebox h3{ box-sizing:border-box; width:var(--pw); max-width:100%; margin:0; padding-bottom:var(--sp-2); border-bottom:1px solid var(--ui-line); text-align:left; }
#root #pausebox::after{ box-sizing:border-box; width:var(--pw); max-width:100%; text-align:right; }

check:
{v:'VER',what:'Settings: the stepper sits within 400px of its name and the card is 17 x 48; the pause title is left-aligned over the button column',
 run:function(){
   if(typeof openSettings!=='function') return 'SKIP: no Settings here';
   var bad=[], l, rows, i, r, k, b, h3, ta, w;
   try{
     openSettings('display'); l=document.getElementById('setlist');
     if(!l) return 'SKIP: no list';
     w=l.getBoundingClientRect().width;
     if(w>830) bad.push('settings list is '+Math.round(w)+'px wide (limit 830)');
     rows=l.querySelectorAll('.row:not(.setjump)');
     for(i=0;i<rows.length;i++){
       r=rows[i]; k=r.firstElementChild; b=r.querySelector(':scope > button');
       if(!k||!b||!b.offsetWidth) continue;
       var d=b.getBoundingClientRect().left-k.getBoundingClientRect().left;
       if(d>440){ bad.push('stepper is '+Math.round(d)+'px from its name (limit 440): '+(k.textContent||'').slice(0,24)); break; }
     }
     h3=document.querySelector('#pausebox h3'); ta=h3?getComputedStyle(h3).textAlign:'';
     if(!h3) bad.push('no pause title');
     else if(ta!=='left'&&ta!=='start') bad.push('pause title is '+ta+', not left-aligned');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ ['settingsmodal'].forEach(function(i){ var q=document.getElementById(i); if(q) q.classList.remove('on'); }); }catch(_k){} try{ __topClear(); }catch(_c){} }
   return bad.length?bad.join('; '):null; }},
